var PANEL_LOG_RING_SIZE = 80;
function createLogRing(capacity = PANEL_LOG_RING_SIZE) {
  const max = Math.max(1, Math.floor(capacity));
  const buf = [];
  return {
    capacity: max,
    push(line) {
      buf.push(line);
      if (buf.length > max) {
        buf.splice(0, buf.length - max);
      }
    },
    lines() {
      return buf.slice();
    },
    clear() {
      buf.length = 0;
    }
  };
}

